#include <iostream>
#include <set>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {5, 3, 5, 1, 3, 9};
    set<int> s(v.begin(), v.end());
    for (int x : s) {
        cout << x << " ";
    }
    cout << endl;
    cout << s.size() << endl;
    return 0;
}

