#include <set>
using namespace std;

int main() {
    set<int> s;
    auto first = s.insert(4);
    auto second = s.insert(4);
    cout << boolalpha << first.second << " " << second.second << endl;
    cout << s.count(4) << " " << s.count(7) << endl;
    return 0;
